// SecondsLeft says "{seconds, plural, one {#s} other {#s}}"
// in the language the app shows under cx.
//
// Seconds left before the verification code changes, written short.
func SecondsLeft(cx *core.Scope, seconds int) string { return For(cx).SecondsLeft(seconds) }

// SecondsLeft is the package's SecondsLeft in the language of msgs.
func (msgs Messages) SecondsLeft(seconds int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.SecondsLeft(seconds))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].SecondsLeft; f != nil {
			return f(seconds)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(seconds)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(seconds))))
				b.WriteString("s")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(seconds))))
				b.WriteString("s")
			}
			return b.String()
		case "zh-Hans":
			var b strings.Builder
			switch i18n.Cardinal("zh-Hans", float64(seconds)) {
			default:
				b.WriteString(i18n.FormatNumber("zh-Hans", float64(seconds)))
				b.WriteString(" 秒")
			}
			return b.String()
		}
	}
}

