// EmptyTrashMessage says "{count, plural, one {# item will be permanently deleted and cannot be recovered.} other {# items will be permanently deleted and cannot be recovered.}}"
// in the language the app shows under cx.
func EmptyTrashMessage(cx *core.Scope, count int) string { return For(cx).EmptyTrashMessage(count) }

// EmptyTrashMessage is the package's EmptyTrashMessage in the language of msgs.
func (msgs Messages) EmptyTrashMessage(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.EmptyTrashMessage(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].EmptyTrashMessage; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" item will be permanently deleted and cannot be recovered.")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" items will be permanently deleted and cannot be recovered.")
			}
			return b.String()
		case "zh-Hans":
			var b strings.Builder
			switch i18n.Cardinal("zh-Hans", float64(count)) {
			default:
				b.WriteString(i18n.FormatNumber("zh-Hans", float64(count)))
				b.WriteString(" 个项目将被永久删除，且无法恢复。")
			}
			return b.String()
		}
	}
}

